import hashlib
import os
import re

from ta_pcmd.py3_string import py3_string

try:
    from asn1PERser import parse_asn1_schema, decode
except ImportError:
    pass
import subprocess
from ta_pcmd.asn_definitions.extract_record_from_standard import protocols_standard_filename,\
    get_record_names_for_documentation
PARSE_PROTOCOLS = ['nsetap-x', 'nsetap']
VERSION_PARSER = {'nsetap-x': re.compile(r'--\s*Version:\s*(\S+)'),
                  'nsetap': re.compile(r'ver\.\s*(\S+)\s*\(ASN1 aligned PER\)')}
RELEASE_CHANGE = '- added {} {}'


def get_version_of_standard(standard_name):
    assert standard_name in protocols_standard_filename,\
        'Standard name: {} not supported, only supproted: {}'\
        .format(standard_name, list(protocols_standard_filename.keys()))
    curr_path = os.sep.join(os.path.abspath(__file__).split(os.sep)[:-1])
    standard_path = os.sep.join([curr_path, 'asn_definitions', protocols_standard_filename[standard_name]])
    with open(standard_path) as f:
        schema = f.read()
        prot_version = VERSION_PARSER[standard_name].search(schema).group(1)
        print('ta_pcmd supported protocol: {} in version: {}'.format(standard_name, prot_version))
    return prot_version


if __name__ == '__main__':
    current_branch = subprocess.check_output('git symbolic-ref --short HEAD', shell=True)
    print('Current branch is: {}'.format(current_branch))
    assert current_branch != 'master',\
        'Cannot run this script on master! Please create own branch by git checkout -b my_branch'
    updated_protocols = []
    curr_path = os.sep.join(os.path.abspath(__file__).split(os.sep)[:-1])
    parsing_out_path = os.sep.join([curr_path, 'asn_definitions'])
    asn1Per_out_filename = 'TraceProtocol.py'
    out_filename_path = os.sep.join([parsing_out_path, asn1Per_out_filename])
    for prot in PARSE_PROTOCOLS:
        standard_path = os.sep.join([curr_path, 'asn_definitions', protocols_standard_filename[prot]])
        hash_path = re.sub('.txt', '.md5', standard_path)
        print('\n\nAnalyzing standard: {}'.format(standard_path))
        with open(standard_path) as f:
            schema = f.read()
            prot_version = VERSION_PARSER[prot].search(schema).group(1)
            print('Prot: {} in version: {}'.format(prot, prot_version))
            available_types = re.findall('::= ([A-Z]+ ?(?:[A-Z]+)?)', schema)
            # print(list(set(available_types)))
        with open(hash_path) as h:
            last_hash = py3_string(h.read())
        current_hash = hashlib.md5(schema.encode('utf-8')).hexdigest()
        print('Current content hash: {}'.format(current_hash))
        print('Last content hash: {}'.format(last_hash))
        if last_hash != current_hash:
            user_answer = input('Do you want to overwrite current version? [enter=no]')
            if user_answer == 'y' or user_answer == 'yes':
                updated_protocols.append((prot, prot_version))
                print('!! Content of : {} is different, parsing is enabled'.format(standard_path))
                print('Started parsing, it may take about 10-30 mins')
                parse_asn1_schema(schema, parsing_out_path)
                print('Parsing complete')
                old_asn1Per_schema = re.sub(r'\.py', r'_{}.py'.format(re.sub(r'-', r'', prot)), out_filename_path)
                os.remove(old_asn1Per_schema)
                print('Removed old version: {}'.format(old_asn1Per_schema))
                os.rename(out_filename_path, old_asn1Per_schema)
                print('Added new version of: {}'.format(old_asn1Per_schema))
                with open(hash_path, 'w+') as h:
                    h.write(current_hash)
                print('Saved new hash: {}'.format(current_hash))
            else:
                print('!! Content of : {} is different, but parsing is disabled'.format(standard_path))
    if len(updated_protocols):
        upper_path = os.path.split(curr_path)[0]
        setup_py_path = os.sep.join([upper_path, 'setup.py'])
        with open(setup_py_path, 'r') as f:
            r_content = f.read()
            current_version_of_lib = re.search(r'version\s*\=\s*\'(\d+(?:\.\d+)*)\'', r_content).group(1)
            print('Current lib version: {}'.format(current_version_of_lib))
            next_lib_version = current_version_of_lib.split('.')[:-1]
            next_lib_version.append(str(int(current_version_of_lib.split('.')[-1]) + 1))
            next_lib_version = '.'.join(next_lib_version)
            print('Next lib version: {}'.format(next_lib_version))
        with open(setup_py_path, 'w') as f:
            new_content = re.sub(r'version\s*\=\s*\'(\d+(?:\.\d+)*)\'', r'version=\'{}\''
                                 .format(next_lib_version), r_content)
            f.write(new_content)
        changelog_path = os.sep.join([upper_path, 'CHANGELOG.md'])
        with open(changelog_path) as f:
            change_content = f.read()
        version_text = ""
        for (protocol, version) in updated_protocols:
            version_text += "\n{}".format(RELEASE_CHANGE.format(protocol, version))
        changed_log_to_add = 'v.{}{}\n\n'.format(next_lib_version, version_text)
        print('Line to add:\n{}'.format(changed_log_to_add))
        with open(changelog_path, 'w') as f:
            f.write(changed_log_to_add + change_content)
        interface_path = os.sep.join([upper_path, 'ta_pcmd', 'interface.py'])
        new_documentation = get_record_names_for_documentation()
        print(new_documentation)
        try:
            print('Adding new record in keyword doc:\n{}'.format(interface_path))
            doc_pattern = re.compile(r'<DOC_TEMPLATE>.*?<\/DOC_TEMPLATE>', re.MULTILINE | re.DOTALL)
            with open(interface_path, 'r+') as f:
                interface_content = f.read()
                interface_content = re.sub(doc_pattern, new_documentation, interface_content)
                f.truncate(0)
                f.write(interface_content)
        except Exception as e:
            print('Exception occured: {} during updating interface.py doc'.format(e))
        print('You can now commit and push new branch to repository.'
              ' Be aware, that some new records may be changed or added.')
        print('If so, unit tests will fail and manual fix would be needed.')
        print('Merge to master only after pipeline succeeds.')
    exit(0)
